// v23.xx (gfx13), HIS ORDER (2026-10-12) on the graphics program, item 3, the animation pass: which way a body is travelling
// across the screen, so its feet step that way. Read off the body's own position from one draw to the next and kept on the
// body (o._ax, o._ay, o._ad), as the jiggle spring and the hair lag are. A second draw in the same frame (the see-through
// ghost) has not moved, so it keeps the last direction. Draw-side only: nothing in the sim reads these fields.
function animDir(o,fl){
  var dx, dy;
  if(!o||typeof o!=='object'||typeof o.x!=='number'||typeof o.y!=='number') return fl;
  dx=(o._ax===undefined)?0:o.x-o._ax; dy=(o._ay===undefined)?0:o.y-o._ay; o._ax=o.x; o._ay=o.y;
  if(Math.abs(dx)>0.02&&Math.abs(dx)>0.35*Math.abs(dy)) o._ad=(dx>0)?1:-1;
  else if(Math.abs(dy)>0.02) o._ad=fl;
  return o._ad||fl;
}
